package com.sathavahana.kalamkari.repository; import com.sathavahana.kalamkari.domain.Product; import org.springframework.data.jpa.repository.EntityGraph; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.util.*; public interface ProductRepository extends JpaRepository<Product,Long>{@EntityGraph(attributePaths = "category") Optional<Product> findBySlugAndActiveTrue(String slug); @EntityGraph(attributePaths = "category") List<Product> findAllByActiveTrue(); @EntityGraph(attributePaths="category") org.springframework.data.domain.Page<Product> findByNameContainingIgnoreCaseOrSlugContainingIgnoreCase(String name,String slug,org.springframework.data.domain.Pageable page); long countByActiveTrue(); long countByActiveFalse(); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select p from Product p where p.id=:id") Optional<Product> findLocked(@org.springframework.data.repository.query.Param("id") Long id);}
